/// `Select-NewerWindow`: `true` when `b` wins over `a` - the newer one that names a window; at the
/// same instant the one whose fullest window is fuller (the threads of one account report at the
/// same moment, and some report a stale share: the highest is the account's).
pub fn newer_wins(a: Option<&Observation>, b: Option<&Observation>) -> bool {
    let named = |w: Option<&Observation>| w.map(|w| w.named()).unwrap_or(false);
    let (bw, b_at) = match b {
        Some(bw) if named(b) && bw.at.is_some() => (bw, bw.at.unwrap()),
        _ => return false,
    };
    let (aw, a_at) = match a {
        Some(aw) if named(a) && aw.at.is_some() => (aw, aw.at.unwrap()),
        _ => return true,
    };
    if b_at > a_at {
        return true;
    }
    if b_at < a_at {
        return false;
    }
    bw.fullest() > aw.fullest()
}

/// The TOTAL, order-independent ranking of two observations of the SAME window at an equal
/// instant, evaluated at `now`: (1) a known future reset beats a known past reset beats a missing
/// one (a past reset means the window is reset, whatever its share); (2) the higher
/// `used_percent`; (3) the later `resets_at`; (4) identical - either. `Greater` when `a` ranks
/// above `b`.
fn cmp_window_rank(
    a: (f64, Option<DateTime<FixedOffset>>),
    b: (f64, Option<DateTime<FixedOffset>>),
    now: DateTime<Utc>,
) -> std::cmp::Ordering {
    let rank = |r: Option<DateTime<FixedOffset>>| match r {
        Some(t) if t.with_timezone(&Utc) > now => 2u8,
        Some(_) => 1,
        None => 0,
    };
    rank(a.1)
        .cmp(&rank(b.1))
        .then(a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal))
        .then(a.1.cmp(&b.1))
}

/// The observation the thread/sub-agent aggregation keeps after seeing `b` ([`newer_wins`] for the
/// newer instant); at an EQUAL instant each window is merged on its own - the higher primary
/// `used_percent` (with its reset) and, independently, the higher secondary - so a fuller weekly
/// window is never hidden behind a fuller 5-hour one.
pub fn merge_observation(a: Option<Observation>, b: Option<&Observation>) -> Option<Observation> {
    let (Some(av), Some(bv)) = (a.as_ref(), b) else {
        return if newer_wins(a.as_ref(), b) {
            b.cloned()
        } else {
            a
        };
    };
    match (av.named(), bv.named(), av.at, bv.at) {
        (true, true, Some(x), Some(y)) if x == y => {
            let pick = |p: &Option<Window>, q: &Option<Window>| match (p, q) {
                (Some(p), Some(q)) => {
                    let key = |w: &Window| {
                        (
                            w.used_percent,
                            w.resets_at
                                .as_deref()
                                .and_then(|r| DateTime::parse_from_rfc3339(r).ok()),
                        )
                    };
                    let now = Utc::now();
                    Some(
                        if cmp_window_rank(key(q), key(p), now) == std::cmp::Ordering::Greater {
                            q
                        } else {
                            p
                        }
                        .clone(),
                    )
                }
                (Some(p), None) => Some(p.clone()),
                (None, q) => q.clone(),
            };
            Some(Observation {
                primary: pick(&av.primary, &bv.primary),
                secondary: pick(&av.secondary, &bv.secondary),
                at: av.at,
                limit_id: av.limit_id.clone(),
            })
        }
        _ => {
            if newer_wins(a.as_ref(), b) {
                b.cloned()
            } else {
                a
            }
        }
    }
}

